void PageHandlerAsyncWaiter::AddSink(
    const std::string& access_code, CastDiscoveryMethod discovery_method, AddSinkResultCode* out_result_code) {
  base::RunLoop loop;
  proxy_->AddSink(std::move(access_code),std::move(discovery_method),
      base::BindOnce(
          [](base::RunLoop* loop,
             AddSinkResultCode* out_result_code
,
             AddSinkResultCode result_code) {*out_result_code = std::move(result_code);
            loop->Quit();
          },
          &loop,
          out_result_code));
  loop.Run();
}

AddSinkResultCode PageHandlerAsyncWaiter::AddSink(
    const std::string& access_code, CastDiscoveryMethod discovery_method) {
  AddSinkResultCode async_wait_result;
  AddSink(std::move(access_code),std::move(discovery_method),&async_wait_result);
  return async_wait_result;
}

void PageHandlerAsyncWaiter::CastToSink(
    ::media_router::mojom::RouteRequestResultCode* out_result_code) {
  base::RunLoop loop;
  proxy_->CastToSink(
      base::BindOnce(
          [](base::RunLoop* loop,
             ::media_router::mojom::RouteRequestResultCode* out_result_code
,
             ::media_router::mojom::RouteRequestResultCode result_code) {*out_result_code = std::move(result_code);
            loop->Quit();
          },
          &loop,
          out_result_code));
  loop.Run();
}

::media_router::mojom::RouteRequestResultCode PageHandlerAsyncWaiter::CastToSink(
    ) {
  ::media_router::mojom::RouteRequestResultCode async_wait_result;
  CastToSink(&async_wait_result);
  return async_wait_result;
}




